using System;using System.IO;using System.Linq;using UnityEngine;using UnityEngine.Rendering;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class BRFinish {
 const string E="Assets/Afrer_Seconds/05.Model/Environment/B2/";static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string O=>R+"/Docs/Review/2026-11-10_B2_SurfaceRefinement/";
 static Scene Check(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B2_Circular.unity"))throw new Exception("Saved B2 required");return s;}
 static void Save(Scene s){foreach(var root in s.GetRootGameObjects().Where(g=>g.name.StartsWith("B2_")))foreach(var t in root.GetComponentsInChildren<Transform>(true))if(PrefabUtility.IsPartOfPrefabInstance(t)){foreach(var c in t.GetComponents<Component>())if(c)PrefabUtility.RecordPrefabInstancePropertyModifications(c);}AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);}
 public static object Lods(){var s=Check();AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);int count=0;var root=s.GetRootGameObjects().Single(g=>g.name=="B2_MachineryNetwork").transform.Find("B2_DetailPass/UpperServiceRoutes");foreach(var hall in root.Cast<Transform>()){var visual=hall.GetChild(0);if(visual.GetComponent<LODGroup>())continue;string id=hall.name.Split('_')[1];var path=E+"BD_"+id+"_UpperWalk_LOD1.fbx";var src=AssetDatabase.LoadAssetAtPath<GameObject>(path);if(!src)throw new Exception("Missing "+path);var original=visual.GetComponentsInChildren<MeshRenderer>();var g=(GameObject)PrefabUtility.InstantiatePrefab(src,visual);g.name="Distance_LOD1";g.transform.localPosition=Vector3.zero;g.transform.localRotation=Quaternion.identity;var far=g.GetComponentsInChildren<MeshRenderer>();foreach(var r in far)r.sharedMaterials=original[0].sharedMaterials;var lg=visual.gameObject.AddComponent<LODGroup>();lg.fadeMode=LODFadeMode.CrossFade;lg.animateCrossFading=true;lg.SetLODs(new[]{new LOD(.12f,original.Cast<Renderer>().ToArray()),new LOD(0,far.Cast<Renderer>().ToArray())});lg.RecalculateBounds();lg.size=16;count++;}Save(s);return new{lodGroups=count};}
 public static object Reflections(){var s=Check();var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));bool on=player.activeSelf;player.SetActive(false);int count=0;try{foreach(var p in s.GetRootGameObjects().Where(g=>g.name.StartsWith("B2_")).SelectMany(g=>g.GetComponentsInChildren<ReflectionProbe>())){p.mode=ReflectionProbeMode.Custom;p.resolution=128;p.backgroundColor=new Color(.025f,.008f,.006f);p.intensity=.65f;string path=E+"Textures/BR_Reflection_"+(++count).ToString("00")+".exr";if(!Lightmapping.BakeReflectionProbe(p,path))throw new Exception("Reflection failed "+p.name);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);p.customBakedTexture=AssetDatabase.LoadAssetAtPath<Cubemap>(path);}}finally{player.SetActive(on);}Save(s);File.WriteAllText(O+"reflections.json",JsonConvert.SerializeObject(new{probes=count}));return new{probes=count};}
 public static object Occlusion(){var s=Check();foreach(var root in s.GetRootGameObjects().Where(g=>g.name.StartsWith("B2_")))foreach(var r in root.GetComponentsInChildren<MeshRenderer>()){if(!r.enabled)continue;var flags=StaticEditorFlags.BatchingStatic|StaticEditorFlags.OccludeeStatic;if(r.GetComponent<MeshCollider>()&&!r.name.StartsWith("BD_"))flags|=StaticEditorFlags.OccluderStatic;GameObjectUtility.SetStaticEditorFlags(r.gameObject,flags);}Save(s);StaticOcclusionCulling.smallestOccluder=2;StaticOcclusionCulling.smallestHole=.25f;StaticOcclusionCulling.backfaceThreshold=100;return new{started=StaticOcclusionCulling.Compute()};}
 public static object Complete(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||!s.path.EndsWith("Level_B2_Circular.unity"))throw new Exception("B2 edit required");if(StaticOcclusionCulling.isRunning)throw new Exception("Occlusion bake still running");foreach(var c in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Camera>(true)))c.useOcclusionCulling=true;Save(s);return new{scene=s.path,saved=!s.isDirty,occlusionRunning=StaticOcclusionCulling.isRunning};}
}
